def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Check if field is quoted
        if line[i] == '"':
            # Parse quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # After closing quote, must be comma or end of line
            if i < len(line) and line[i] != ',':
                return None

            fields.append(field)

            # Skip the comma if present
            if i < len(line):
                i += 1
        else:
            # Parse unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Skip the comma if present
            if i < len(line):
                i += 1

    return fields

